const icons={overview:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',desk:'M3 19h18 M6 14V8 M10 17V4 M14 13V7 M18 16V3',review:'M8 3h8v3H8z M6 5H4v16h16V5h-2 M8 13l3 3 5-6',screener:'M4 4h16 M6 10h12 M9 16h6 M11 16v5',journal:'M5 3h14v18H5z M9 8h6 M9 12h6 M9 16h4',market:'M3 12h4l3-8 4 16 3-8h4',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',arrow:'M5 12h14 M14 7l5 5-5 5',moon:'M19 15A8 8 0 0 1 9 5a8 8 0 1 0 10 10',sun:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v2 M12 20v2 M2 12h2 M20 12h2 M5 5l2 2 M17 17l2 2',check:'M5 12l4 4L19 6',layers:'M3 7l9-5 9 5-9 5z M3 12l9 5 9-5 M3 17l9 5 9-5'};
function icon(k){return `<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[k]||icons.arrow}"/></svg>`}
const pages={overview:'Обзор',desk:'Рабочее место',review:'Проверка',screener:'Скринер',journal:'Журнал',market:'Контекст рынка',settings:'Настройки'};
const state={page:'overview',mode:'context',inspector:'scenario',market:'now',setting:'assets',filter:'all',layers:false,watch:true,enabled:true,reviewDone:false,reviewResult:'',theme:'dark',search:'',bucket:'all',log:'all',filters:false,asset:'BTC',dirty:false};
const assets=[['ENA','0,2066','10,31%','SSL снят','binance'],['LINK','12,85','3,5%','SSL снят','binance'],['NEAR','2,57','1,88%','Ретест','binance'],['AVAX','19,72','1,09%','SSL снят','binance'],['SUI','2,31','4,94%','SSL снят','binance'],['HBAR','0,142','6,6%','Ретест','binance'],['TAO','308,4','4,99%','SSL снят','binance'],['QNT','88,12','71,47%','Ретест','binance']];
function badge(t,c=''){return `<span class="badge ${c}">${t}</span>`}
function tabs(items,current,attr){return `<div class="tabs" role="group">${items.map(([id,t])=>`<button ${attr}="${id}" class="${current===id?'active':''}" aria-pressed="${current===id}">${t}</button>`).join('')}</div>`}
function head(eyebrow,title,sub,actions=''){return `<div class="pagehead"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="sub">${sub}</p></div><div class="row">${actions}</div></div>`}
function facts(items){return `<dl class="facts">${items.map(([a,b])=>`<div><dt>${a}</dt><dd>${b}</dd></div>`).join('')}</dl>`}
function chart(h1=false,alt=false){
 let s='';for(let x=20;x<900;x+=100)s+=`<line x1="${x}" y1="25" x2="${x}" y2="430" stroke="var(--grid)"/>`;for(let y=35;y<430;y+=65)s+=`<line x1="15" y1="${y}" x2="900" y2="${y}" stroke="var(--grid)"/><text x="910" y="${y+4}" fill="var(--muted)" font-size="11">${alt?(1.7-y/280).toFixed(2):(85500-y*9).toLocaleString('ru-RU')}</text>`;
 s+=`<rect x="380" y="140" width="520" height="37" fill="var(--accent)" opacity=".12"/><line x1="380" x2="900" y1="140" y2="140" stroke="var(--accent)" opacity=".6"/><line x1="380" x2="900" y1="177" y2="177" stroke="var(--accent)" opacity=".6"/><text x="770" y="132" fill="var(--muted)" font-size="11">${alt?'Зона ретеста':'OB · D1 / 83 528,98'}</text><rect x="540" y="295" width="360" height="24" fill="var(--green)" opacity=".09"/><line x1="540" x2="900" y1="319" y2="319" stroke="var(--green)" opacity=".5"/><text x="765" y="340" fill="var(--muted)" font-size="11">${alt?'L / 0,194':'SSL · H1 / 81 603,52'}</text>`;
 let prev=110;for(let i=0;i<88;i++){let close=110+i*1.9+Math.sin(i*.15)*65+Math.sin(i*.69)*13;if(i>62)close-=Math.sin((i-62)/26*Math.PI)*104;const x=20+i*9.8,c=close<prev?'var(--green)':'var(--red)';s+=`<line x1="${x}" x2="${x}" y1="${Math.min(close,prev)-7-i%9}" y2="${Math.max(close,prev)+11}" stroke="${c}"/><rect x="${x-3}" y="${Math.min(close,prev)}" width="6" height="${Math.max(2,Math.abs(close-prev))}" fill="${c}"/>`;prev=close;}
 s+=`<line x1="15" x2="900" y1="274" y2="274" stroke="var(--muted)" stroke-dasharray="3 4"/><rect x="902" y="263" width="70" height="23" rx="3" fill="var(--raised)"/><text x="907" y="279" fill="var(--text)" font-size="11">${alt?'0,2066':'82 577,54'}</text>`;
 if(h1)s+=`<text x="442" y="268" fill="var(--red)" font-size="11">BOS ↓</text><text x="625" y="323" fill="var(--green)" font-size="11">HL ↑</text><text x="743" y="195" fill="var(--red)" font-size="11">LH ↓</text>`;
 ['06 окт','07 окт','08 окт','09 окт','10 окт'].forEach((t,i)=>s+=`<text x="${30+i*205}" y="457" fill="var(--muted)" font-size="11">${t}</text>`);
 const yLabels=[0,1,2,3,4,5,6].map(i=>`<span style="top:${(35+i*65)/480*100}%">${alt?(1.7-(35+i*65)/280).toFixed(2):(85500-(35+i*65)*9).toLocaleString('ru-RU')}</span>`).join('');
 return `<div class="chart"><svg viewBox="0 0 980 480" preserveAspectRatio="none" role="img" aria-label="Демонстрационный свечной график с зоной предложения и уровнем ликвидности">${s}</svg><div class="chart-axis num" aria-hidden="true">${yLabels}<b style="top:57%">${alt?'0,2066':'82 577,54'}</b></div><div class="chart-annotation" style="top:26%">${alt?'Зона ретеста':'OB · D1'}</div><div class="chart-annotation" style="top:69%">${alt?'L / 0,194':'SSL · H1'}</div><span class="chart-stamp"><strong>LF</strong>Демо · ${h1?'H1':alt?'W1':'D1'}</span></div><div class="chart-dates"><span>06 окт</span><span>07 окт</span><span>08 окт</span><span>09 окт</span><span>10 окт</span></div>`;
}
function scenario(){return `<div class="block"><div class="row spread"><span class="sectionlabel">СЦЕНАРИЙ H1</span>${badge('Ожидание','amber')}</div><div class="scenario-title">SHORT <span class="muted">/ откат</span></div><p class="sub">BOS ↓ · закрытие ниже 82 400,00<br>09.10.2026 · 22:59 МСК</p></div><div class="block">${facts([['Основание','OB D1 · FVG W1 + 2'],['Зона входа','83 528,98'],['PD H1','82 285,71–83 528,98'],['Середина PD','82 907,35']])}</div><div class="block"><div class="sectionlabel">УСЛОВИЕ ОТМЕНЫ</div><p class="small">Закрытие H1 выше 83 528,98 — исходной опоры ноги.</p></div><div class="note">Предварительный диапазон PD. Подтверждение сценария не означает доступный вход.</div><button class="${state.watch?'':'primary'} full" data-action="watch">${icon('check')} ${state.watch?'Наблюдаю':'Наблюдать'}</button><details><summary>Основания и качество данных</summary><p class="small muted">Котировка: демо · 2 с назад. Свечи H1: демо. Качество каждого источника отображается отдельно.</p></details>`}
function overview(){return head('РЫНОЧНЫЙ МОНИТОРИНГ','Обзор рынка','Наблюдение, проверка разметки и текущие сценарии.',`<button data-page="settings">Управление активами</button>`)+`<div class="metrics">${[['review','На проверку','0','Очередь пуста'],['zone','Цена в зоне','0','По включённым активам'],['confirmed','Сценарий подтверждён','0','По состоянию расчёта']].map(([f,t,n,s])=>`<button class="panel metric" data-overview-filter="${f}"><span>${t}<small>${s}</small></span><strong class="num">${n}</strong></button>`).join('')}</div><div class="two-col"><div><section class="panel"><div class="panelhead"><h2>Список наблюдения <span class="muted">/ 1</span></h2>${badge('Демо','blue')}</div><div class="filters">${tabs([['all','Все'],['attention','Требуют внимания'],['watch','Наблюдаю']],state.filter,'data-filter')}</div>${['attention','zone','confirmed'].includes(state.filter)?`<div class="empty"><strong>Нет активов по этому фильтру</strong>Список наблюдения доступен во вкладке «Все».<p><button data-filter="all">Показать все</button></p></div>`:`<div class="table-scroll"><table><thead><tr><th>Актив / площадка</th><th>Рыночное состояние</th><th class="right">Цена, USDT</th><th>Данные</th></tr></thead><tbody><tr class="selectable selected" data-page="desk"><td><strong>BTC / USDT</strong><small>Binance · Spot</small></td><td>${badge('SHORT · ожидание отката','amber')}</td><td class="right num">82 577,54</td><td>${badge('Актуальны','green')}<small>Демо · 2 с назад</small></td></tr></tbody></table></div>`}</section><section class="panel under"><div class="panelhead"><h2>Последние изменения</h2><button class="quiet" data-page="journal">В журнал ${icon('arrow')}</button></div><div class="list-item row spread"><div><strong class="small">BTC / USDT · снятие ликвидности и тест FVG</strong><p class="sub">09 окт · 23:59 МСК · 13 записей в группе</p></div>${badge('Рынок')}</div><div class="list-item row spread"><div><strong class="small">Приближение к зоне FVG</strong><p class="sub">Цена 82 500,01 · 5 записей в группе</p></div>${badge('23:57')}</div></section><div class="audit-mini"><p>Приоритет отражает необходимость внимания. Состояние рынка и свежесть данных показаны раздельно.</p></div></div><aside class="panel"><div class="panelhead"><h2>BTC / USDT</h2><span class="muted small">Binance · Spot</span></div><div class="pad">${scenario()}<button class="primary full" data-page="desk">Открыть рабочее место ${icon('arrow')}</button></div></aside></div>`}
function layerPanel(){return `<div class="layers">${[['Контекст',['Зоны D1','Зоны W1','Все ТФ','Кандидаты','История']],['Структура H1',['HH / HL / LH / LL','BOS / SMS','Ожидаемые уровни','Зоны H1','OB / FVG','BSL / SSL']],['Отображение',['Середины','Подписи','HTF-контекст','Только актуальные идеи','Диагностические точки']]].map(([t,items])=>`<div><h3>${t}</h3>${items.map((l,i)=>`<label><input type="checkbox" ${i<2?'checked':''}> ${l}</label>`).join('')}</div>`).join('')}<p class="sub">Прототип: настройки слоёв иллюстративны. Полный контракт — в ТЗ.</p></div>`}
function inspector(){if(state.inspector==='scenario')return scenario();if(state.inspector==='zones')return `<div class="block">${tabs([['live','Актуальные'],['candidate','Кандидаты'],['archive','Архив']],state.bucket,'data-bucket')}</div><label class="small muted">Тип зоны <select aria-label="Тип зоны"><option>Все типы</option><option>OB</option><option>FVG</option><option>SSL</option><option>BSL</option><option>PRB</option><option>Breaker</option><option>Ручная</option></select></label><button class="zone-row" data-modal="zone"><span>OB · D1<small>83 528,98 · выше цены</small></span>${badge('Актуальна','blue')}</button><button class="zone-row" data-modal="zone"><span>SSL · H1<small>81 603,52 · ниже цены</small></span>${badge('Уровень')}</button><button class="full" data-action="zone-table">Все зоны · таблица</button><p class="sub">Демонстрационный список. Фильтры не меняют рыночное состояние.</p>`;return `<div class="block">${badge('Неполные данные','amber')}<h3 style="margin-top:16px">Риск после локального максимума</h3><p class="small">Дневная свеча закрылась ниже максимума. Лонг-ликвидации выше своей нормы.</p></div><div class="note">Часовые данные Coinglass недоступны. Удержание минимума тремя H1 не проверено.</div><p class="small muted">Funding: наблюдаемая ставка, выплата не подтверждена.</p><button class="full" data-page="market">Открыть контекст рынка ${icon('arrow')}</button>`}
function desk(){return head('РАБОЧЕЕ МЕСТО','BTC / USDT','Binance · Spot · данные демо',`<div class="headline-actions"><div class="price num">82 577,54 <span class="small muted">USDT</span></div><div class="sub">Котировка · 2 с назад</div></div>`)+`<div class="status-strip"><span>${badge('SHORT · ожидание отката','amber')}</span><span>${badge(state.enabled?'Анализ включён':'Анализ выключен',state.enabled?'green':'')}</span><button class="quiet small" data-action="enabled">${state.enabled?'Выключить анализ':'Включить анализ'}</button></div><div class="workspace"><aside class="panel watchlist"><div class="sectionlabel">АКТИВЫ</div><button class="nav-button active" data-page="desk">BTC / USDT<small class="num">82 577,54</small><small>Ожидание отката</small></button><button class="full small" data-page="settings">Управление</button></aside><div><section class="panel"><div class="chartbar">${tabs([['context','Контекст HTF'],['h1','Структура H1']],state.mode,'data-mode')}<div class="row"><select aria-label="Таймфрейм свечей" id="tf"><option>${state.mode==='h1'?'H1':'D1'}</option><option>W1</option></select><button data-action="layers" aria-expanded="${state.layers}">${icon('layers')} Слои</button><button data-modal="manual">+ Зона</button></div></div>${state.layers?layerPanel():''}${chart(state.mode==='h1')}<div class="chart-bottom row spread"><span>${state.mode==='h1'?'HH / HL / LH / LL · BOS / SMS':'D1 + W1 · только актуальные зоны'}</span><button class="quiet small" data-action="focus">К текущей цене</button></div></section><section class="panel under"><div class="panelhead"><h2>${state.mode==='h1'?'Зоны сценария':'Зоны и события'}</h2><button class="quiet" data-page="journal">Журнал ${icon('arrow')}</button></div><div class="pad small muted">Активных зон входа нет. Показана структура рынка в ожидании отката.</div></section></div><aside class="panel inspector"><div class="panelhead">${tabs([['scenario','Сценарий'],['zones','Зоны'],['context','Контекст']],state.inspector,'data-inspector')}</div><div class="pad">${inspector()}</div></aside></div>`}
function review(){return head('КОНТРОЛЬ РАЗМЕТКИ','Проверка зон','Решение о геометрии и оценка жизненного цикла отображаются отдельно.',`<button data-action="export">Экспорт проверок</button>`)+(state.reviewDone?`<section class="panel empty">${icon('check')}<strong>Демонстрационная проверка завершена</strong>${state.reviewResult}<p>Результат существует только в макете.</p><p><button data-action="reset-review">Вернуть пример</button> <button class="primary" data-page="overview">К обзору</button></p></section>`:`<div class="review-layout"><aside class="panel watchlist"><div class="sectionlabel">ОЧЕРЕДЬ · ДЕМО 1</div><select aria-label="ТФ кандидатов"><option>D1 + W1</option><option>D1</option><option>W1</option></select><button class="nav-button active">BTC / USDT<small>OB · D1 · #18</small><small>Проверить границы</small></button><p class="sub">На исходном обзоре очередь пуста. Здесь показан пример задачи.</p></aside><section class="panel"><div class="chartbar"><h2>OB · D1 / #18</h2>${badge('Кандидат','amber')}</div>${chart()}<div class="chart-bottom">Выделенная зона · границы и свеча основания</div></section><aside class="panel pad"><div class="sectionlabel">ЗАДАЧА #18</div><h2>Проверьте границы зоны</h2><p class="sub">Сопоставьте диапазон с исходной свечой и правилом OB.</p>${facts([['Инструмент','BTC / USDT'],['Диапазон','83 528,98–84 379,31'],['Состояние','Кандидат'],['Оценка геометрии','Не выполнена']])}<label class="small muted"><p>Комментарий</p><textarea aria-label="Комментарий к проверке" rows="3" style="width:100%;margin-top:8px"></textarea></label><div class="review-actions"><button class="primary" data-decision="Подтверждено">Подтвердить</button><button class="danger" data-decision="Отклонено: неверный тип">Отклонить</button></div><button class="full" data-modal="bounds">Исправить границы</button><details><summary>Другие решения</summary>${['Другое основание','Сейчас неактуально','Уже Breaker','Нет контекста'].map(t=>`<button class="full small" data-decision="${t}">${t}</button>`).join('')}</details><details><summary>История оценок и правок</summary><p class="small muted">В демонстрационной задаче оценок ещё нет.</p></details><button class="full" data-page="desk">Открыть актив</button></aside></div>`)}
const logs=[['23:59','Рынок','Снятие SSL/BSL и тест середины FVG D1','13 записей','market'],['23:57','Рынок','Приближение к зоне FVG · 2%','5 записей','market'],['22:59','Рынок','BOS ↓ · закрытие H1 ниже 82 400,00','1 запись','market'],['22:58','Доставка','Уведомление доставлено в Telegram','1 запись','delivery']];
function journal(){let rows=logs.filter(r=>state.log==='all'||r[4]===state.log);if(state.log==='decision'&&state.reviewDone)rows=[['00:09','Решение',state.reviewResult,'1 запись','decision']];return head('ИСТОРИЯ И АУДИТ','Журнал','Рыночные события, решения пользователя и доставка уведомлений.')+`<section class="panel"><div class="filters spread">${tabs([['all','Все'],['market','Рынок'],['decision','Решения'],['delivery','Доставка']],state.log,'data-log')}<div class="row"><select aria-label="Актив журнала"><option>Все активы</option><option>BTC / USDT</option></select><input type="date" aria-label="Дата журнала" value="2026-10-09"></div></div>${rows.length?rows.map(([time,type,title,count])=>`<div class="log-row"><div class="num">${time}<small class="muted" style="display:block">09 окт · МСК</small></div><div class="log-asset">${type}</div><div><strong>${title}</strong><p class="sub">BTC / USDT · ${count}${count!=='1 запись'?' · группа раскрывается':''}</p></div><button data-modal="event">Открыть</button></div>`).join(''):`<div class="empty"><strong>Решений за этот период нет</strong>После проверки разметки здесь появится запись.</div>`}</section><p class="sub">Группировка — только способ отображения. Исходные записи, идентификаторы и времена сохраняются.</p>`}
function marketNow(){return `<div class="content-grid"><div><section class="panel pad block"><div class="row spread"><h2>Текущая ситуация</h2>${badge('Неполные данные','amber')}</div><div class="scenario-title">Повышенная активность ликвидаций</div><p class="small">После локального максимума дневная свеча закрылась ниже него. Доля лонг-ликвидаций выше своей нормы.</p><div class="note" style="margin-top:18px">Наблюдение за рынком. Это состояние не создаёт заявку и не задаёт направление сделки.</div><p class="sub">Источник цены: Binance BTCUSDT Spot · демо</p></section><section class="panel"><div class="panelhead"><h2>Проверка условий</h2><span class="small muted">4 сетапа</span></div>${[['A','Заблокирован','Удержание минимума тремя H1 не проверено'],['B','Заблокирован','Растущий OI удерживает запрет'],['V','Заблокирован','Действует запрет каскада ликвидаций'],['G','Не применим','Наблюдаемая ставка положительная']].map(([id,status,reason])=>`<div class="list-item"><div class="row spread"><strong class="small">Сетап ${id}</strong>${badge(status,status==='Не применим'?'':'amber')}</div><p class="sub">${reason}</p><details><summary>Условия и зависимости</summary>${facts([['Живой кандидат минимума','Выполнено'],['LIQ01 + LIQ02','Выполнено'],['Три закрытые H1','Неизвестно'],['OI в монетах снижается','Выполнено']])}</details></div>`).join('')}</section></div><aside><section class="panel pad block"><h2>Производные данные</h2>${facts([['Лонг-ликвидации','93,99%'],['OI в монетах','Снижается'],['Funding','Наблюдаемый · +'],['Выплата funding','Не подтверждена']])}<p class="sub">Процент — доля ликвидаций, не вероятность сценария.</p></section><section class="panel pad"><h2>Доступность источников</h2>${facts([['Binance · цена','Демо / актуально'],['Coinglass · H1','Недоступно'],['Coinglass · D1','Демо / доступно']])}<p class="sub">Неизвестное условие сохраняет статус «Не проверено».</p></section></aside></div>`}
function marketFeed(){return `<section class="panel">${[['09:07','Утренняя сводка','MORNING_DIGEST'],['04:13','Лонг-ликвидации после максимума','POST_HIGH_LONG_CASCADE'],['04:13','Риск каскада при росте OI','CASCADE_OI_RISING_RISK'],['04:13','Наблюдение отскока после широкого дня','RED_WIDE_DAY_REBOUND_WATCH'],['04:13','Наблюдение отскока после серии снижений','RED_STREAK_REBOUND_WATCH']].map(([time,t,id])=>`<div class="log-row"><div class="num">${time}<small class="muted" style="display:block">09 окт · МСК</small></div><span class="log-asset">${badge('Появилось','blue')}</span><div><strong>${t}</strong><details><summary>Код события</summary><p class="small muted">${id} · appeared</p></details></div><button data-modal="event">Открыть</button></div>`).join('')}</section>`}
function calendar(){let d='';['Пн','Вт','Ср','Чт','Пт','Сб','Вс'].forEach(t=>d+=`<div class="day dim" style="min-height:32px">${t}</div>`);for(let i=0;i<35;i++){const n=i-2;d+=`<div class="day ${n===9?'today':n<1||n>31?'dim':''}">${n<1?30+n:n>31?n-31:n}${n===9?'<small>Дата источника</small>':''}${n===31?'<small>Конец месяца</small>':''}</div>`}return `<div class="content-grid"><section class="panel"><div class="panelhead"><h2>Октябрь 2026</h2>${badge('Календарь UTC')}</div><div class="calendar-grid">${d}</div></section><aside class="panel pad"><h2>Календарный контекст</h2>${facts([['Дата источника UTC','09.10.2026'],['Неделя месяца','2'],['Конец месяца','Выключен'],['Сезонная цепочка','Неактивна']])}<div class="note" style="margin-top:18px">Календарь не задаёт направление сделки. МСК используется для журнала, UTC — для расчёта календарных условий.</div><p class="sub">Макет календаря расширяет представление существующих данных. Экономические события и новые источники не добавлены.</p></aside></div>`}
function rules(){return `<p class="sub block">Пороговые значения и смысл правил сохраняются. Коды доступны для сверки с системой.</p><div class="rules-grid">${[['LIQ01','Доля лонг-ликвидаций','Строго выше 60%. Значение ровно 60% не выполняет условие.','Правило стратегии'],['LIQ02','Ликвидации относительно нормы','Не ниже 1,9 медианы за 90 предшествующих дней. Это не доказанное дно.','Инженерное значение'],['OI02','Запрет при росте OI','Каскад и рост OI в монетах удерживают запрет до конца дня c+7. Без H1-данных запрет досрочно не снимается.','Правило стратегии'],['FR03','Подтверждённая выплата funding','Порог +0,01% относится к выплаченной 8-часовой ставке. Наблюдаемое OHLC его не включает.','Правило стратегии'],['A','Наблюдение A','Кандидат минимума, каскад в том же четырёхдневном окне, удержание, падение OI и снятый запрет. Совпадение не является вероятностью.','Правило стратегии'],['study','Ограничения исследования','Проценты и t-статистика источника на нашем ряду не проверены и не выводятся на карточку.','Факт источника']].map(([id,t,text,cl])=>`<article class="panel rule"><div class="row spread"><h3>${t}</h3>${badge(id)}</div><p>${text}</p><div class="sub">${cl}</div></article>`).join('')}</div>`}
function market(){return head('УСЛОВИЯ И ЗАВИСИМОСТИ','Контекст рынка','Ситуации, производные данные и календарные ограничения.')+`<div class="block">${tabs([['now','Состояние'],['feed','Лента'],['calendar','Календарь'],['rules','Правила']],state.market,'data-market')}</div>`+({now:marketNow,feed:marketFeed,calendar,rules}[state.market])()}
function screener(){let rows=assets.filter(a=>a[0].toLowerCase().includes(state.search.toLowerCase()));if(state.bucket==='new')rows=[];if(state.bucket==='retest')rows=rows.filter(a=>a[3]==='Ретест');return head('АЛЬТКОИНЫ / D1','Скринер','Сравнивайте сетапы перед переходом к графику.',`<button data-modal="processing">Обработка</button>`)+`<div class="row spread block">${tabs([['all','Активные · 125'],['new','Новые входы · 0'],['retest','Ретест · 0'],['review','Проверка · 108'],['history','История · 26']],state.bucket,'data-bucket')}<div class="row"><button data-action="filters" aria-expanded="${state.filters}">Фильтры</button></div></div><section class="panel"><div class="filters spread"><input id="search" class="toolbar-search" type="search" placeholder="Поиск актива" aria-label="Поиск актива" value="${state.search}"><div class="row"><select aria-label="Биржа"><option>Все биржи</option><option>Binance</option><option>Bybit</option></select><select aria-label="Сортировка"><option>Ранг капитализации</option><option>Расстояние до входа</option><option>Дата события</option></select></div></div>${state.filters?`<div class="pad"><div class="screen-filters">${['Ранг: от','Ранг: до','Возраст, дней: от','Просадка, %: от'].map(t=>`<label>${t}<input type="number" min="0"></label>`).join('')}</div><div class="row"><select aria-label="Структура"><option>Все структуры</option><option>BOS</option><option>SMS</option></select><select aria-label="Стадия"><option>Все стадии</option><option>Формируется</option><option>Зрелая</option></select><button data-action="apply-filters">Применить</button><button data-action="reset-filters">Сбросить</button></div></div>`:''}<div id="screen-table">${screenerTable(rows)}</div></section><p class="sub">Восемь демонстрационных строк. Счётчики взяты из скриншота и не пересчитываются по этому фрагменту. Расстояние до входа — метрика ранжирования, не торговый сигнал.</p>`}
function screenerTable(rows){return rows.length?`<div class="table-scroll"><table><thead><tr><th>Актив</th><th>Состояние сетапа</th><th>Событие</th><th class="right">Цена D1</th><th class="right">До входа</th><th>Данные</th></tr></thead><tbody>${rows.map(a=>`<tr class="selectable" data-setup="${a[0]}"><td><strong>${a[0]}</strong><small>${a[4]} · ${a[0]}USDT</small></td><td>${badge('Подтверждён','green')}</td><td>${a[3]}</td><td class="right num">${a[1]}</td><td class="right num">${a[2]}</td><td><small>09 окт · D1</small>${icon('arrow')}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty"><strong>Сетапов не найдено</strong>Измените поиск или выбранный фильтр.</div>`}
function setup(){return head('СКРИНЕР / ДЕТАЛИ',`${state.asset} / USDT`,'Binance · подтверждённый сетап · история закрытий D1',`<button data-page="screener">← К скринеру</button>`)+`<div class="two-col"><div><section class="panel"><div class="chartbar">${tabs([['setup','Сетап'],['history','История'],['none','Без событий']],'setup','data-chart-view')}<div class="row"><select aria-label="Таймфрейм сетапа"><option>W1</option><option>D1</option></select><button data-action="layers">Слои</button><button data-action="focus">180D</button><button data-action="focus">Весь диапазон</button></div></div>${state.layers?layerPanel():''}${chart(false,true)}<div class="chartbar"><span class="sub">Недельная свеча незавершённая · расчёт по закрытиям D1</span><div class="row"><button data-action="png">PNG</button><button data-action="png2">PNG 2×</button></div></div></section><section class="panel under"><div class="panelhead"><h2>События сетапа</h2><input type="date" aria-label="Начальная дата событий"></div>${['BOS обратной структуры','SSL снят','Манипуляция завершена'].map(t=>`<div class="list-item row spread"><span class="small">08.10.2026 · 03:00 МСК</span><span class="small">${t}</span><button class="quiet small" data-action="focus">К свече</button></div>`).join('')}</section></div><aside class="panel pad"><div class="row spread"><h2>Состояние сетапа</h2>${badge('Подтверждён','green')}</div>${facts([['Сейчас','SSL снят'],['Основание','BOS · 24.11.2024'],['Вход A · закрытие','0,6679'],['Вход B · ретест','0,43415–0,6743'],['До зоны входа','10,31%']])}<p class="sub">Входы A/B — историческая фиксация. Текущая заявка не создаётся.</p><div class="block" style="margin-top:22px"><h3>Цели</h3>${facts([['TP1 · достигнута','1,1546'],['TP2 · ожидается','1,6349'],['TP3 · ожидается','2,1152'],['TP4 · ожидается','2,5955']])}</div><div class="note">Срок ретеста истёк 09.12.2024. Уровень отмены ≤ 0: линия на графике не отображается.</div><button class="full" data-modal="range">Редактировать диапазон</button><details><summary>Почему найдено</summary><p class="small muted">Старт 05.08.2024. Диапазон L 0,194 · U 0,6743 · M 0,43415. Подтверждение BOS.</p></details><p class="sub">Пример деталей ENA. При выборе других активов значения остаются демонстрационными.</p></aside></div>`}
const settingNames={assets:'Активы',notify:'Уведомления',appearance:'Оформление',analysis:'Правила анализа'};
function field(t,note,v,type='number'){return `<div class="field"><label>${t}<small>${note}</small></label><input aria-label="${t}" type="${type}" value="${v}" data-setting-field></div>`}
function settingsBody(){if(state.setting==='assets')return `<h2>Активы и источники</h2><p class="sub">Выключение останавливает свечи, котировки и расчёт. История сохраняется.</p>${[['BTC / USDT','Binance · Spot',true],['ETH / USDT','Binance · Spot',false],['SOL / USDT','Binance · Spot',false],['ZEC / USDT','Binance · Spot',false],['HYPE / USDT','Binance · Spot',false],['HYPE','Hyperliquid · Spot',false]].map(([a,v,on])=>`<div class="field"><label>${a}<small>${v}</small></label><button data-action="asset-toggle" aria-pressed="${on}">${on?'Выключить':'Включить'}</button></div>`).join('')}`;
if(state.setting==='appearance')return `<h2>Оформление</h2><p class="sub">Тема хранится в браузере. Изменение не запускает пересчёт.</p><div class="field"><label>Тема интерфейса</label><select id="theme-select" aria-label="Тема интерфейса"><option value="dark" ${state.theme==='dark'?'selected':''}>Тёмная</option><option value="light" ${state.theme==='light'?'selected':''}>Светлая</option><option value="system">Как в системе</option></select></div><div class="note" style="margin-top:20px">Табличные числа, семантические цвета и контраст сохраняются в обеих темах.</div>`;
if(state.setting==='notify')return `<div class="row spread"><h2>Уведомления</h2>${badge('Telegram · демо','green')}</div>${field('Пауза повторов, часы','Отсчёт от успешной доставки. Истечение паузы не создаёт событие.',120)}${field('Тихая сводка, минуты','Приближения, промежуточная глубина и состояние источников.',15)}${field('Цель доставки, секунды','Целевой интервал, не гарантия.',120)}<div class="field"><label>Только проверенные зоны<small>Автоматические кандидаты не отправляют уведомления до подтверждения.</small></label><select aria-label="Только проверенные зоны" data-setting-field><option>Выключено</option><option>Включено</option></select></div>${field('События H1','В production — выбор отдельных событий вместо строки кодов.','bos_sms,entries_ready,touch,sweep_outcome,cancellation','text')}<div class="field"><label>Часовой пояс<small>Время интерфейса и журнала.</small></label><span>Москва · UTC+3</span></div>`;
return `<h2>Правила анализа</h2><p class="sub">Версия 0.2 · сервер определяет группы и применимость параметров.</p>${field('История D1, дни','Глубина загружаемой истории.',365)}${field('История W1, дни','Глубина загружаемой истории.',730)}${field('Запасное окно поиска, дни','Сохранённые активные зоны не удаляются.',180)}${field('Приближение к зоне, %','Для API 2% преобразуются в долю 0,02.',2)}${field('Глубина ослабления, %','Для API 50% = 0,5.',50)}${field('Глубина отработки, %','Для API 90% = 0,9.',90)}<details><summary>Структура H1 и поиск зон</summary>${field('Свечи слева','Подтверждение пивота.',3)}${field('Свечи справа','Подтверждение после закрытия.',3)}</details><details><summary>Экспериментальные параметры</summary><div class="note">Полный список определяется сервером. Значения не калиброваны; предупреждение сохраняется.</div></details>`}
function settings(){return head('РАБОЧЕЕ ПРОСТРАНСТВО','Настройки','Активы, уведомления и параметры анализа.')+`<div class="settings-layout"><nav class="settings-nav" aria-label="Разделы настроек">${Object.entries(settingNames).map(([id,t])=>`<button class="nav-button ${state.setting===id?'active':''}" data-setting="${id}" aria-pressed="${state.setting===id}">${t}</button>`).join('')}</nav><div><section class="panel pad">${settingsBody()}</section>${['notify','analysis'].includes(state.setting)?`<div class="savebar"><small id="dirty-label">${state.dirty?'Есть несохранённые изменения':'Изменений нет'}</small><div class="row"><button data-action="cancel-settings">Отменить</button><button class="primary" data-action="save-settings" ${state.dirty?'':'disabled'}>Сохранить</button></div></div>`:''}</div></div>`}
function render(){const p=state.page==='setup'?'screener':state.page;$('#nav').innerHTML=Object.entries(pages).map(([k,t])=>`<button class="nav-button ${k==='settings'?'mobile-settings':''} ${p===k?'active':''}" data-page="${k}" ${p===k?'aria-current="page"':''}>${icon(k)}<span>${t}</span>${k==='review'?'<span class="count">0</span>':''}</button>`).join('');$('#settings-nav').innerHTML=`${icon('settings')}<span>Настройки</span>`;$('#settings-nav').classList.toggle('active',p==='settings');$('#crumb').textContent='Рабочее пространство / '+(pages[p]||'Скринер');$('#theme').innerHTML=icon(state.theme==='dark'?'sun':'moon');$('#main').innerHTML=({overview,desk,review,journal,market,screener,setup,settings}[state.page]||overview)();document.documentElement.dataset.theme=state.theme;}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',4000)}
function openModal(type){const d=$('#dialog');const title={manual:'Добавить ручную зону',bounds:'Исправить границы',range:'Редактировать диапазон',event:'Детали события',zone:'OB · D1 / инспектор зоны',processing:'Обработка скринера'}[type];let body='';
 if(['manual','bounds','range'].includes(type)){body=`<p class="sub">Демонстрационная форма · изменения не отправляются на сервер.</p>${type==='manual'?'<label>Режим<select><option>Диапазон</option><option>Уровень</option></select></label>':''}<label>Нижняя граница<input id="lower" type="number" step="any" value="${type==='range'?'0.194':'83528.98'}"></label><label>Верхняя граница<input id="upper" type="number" step="any" value="${type==='range'?'0.6743':'84379.31'}"></label><label>${type==='range'?'Начало базы':'Свеча-якорь'}<input type="datetime-local" value="2026-10-09T03:00"></label>${type==='manual'?'<label>Направление<select><option>Медвежье</option><option>Бычье</option></select></label><label>Таймфрейм<select><option>D1</option><option>W1</option></select></label><label>Типовое правило<select><option>OB</option><option>FVG</option><option>Без правила</option></select></label><label>Название<input></label>':''}<label>Комментарий<textarea rows="2"></textarea></label><p id="form-error" class="small danger" role="alert"></p><div class="row"><button data-action="close">Отмена</button>${type==='range'?'<button data-action="range-preview">Проверить</button>':''}<button class="primary" data-form-save="${type}">Сохранить пример</button></div>`}
 if(type==='event')body=`${facts([['Актив','BTC / USDT'],['Время','09.10.2026 · 23:59 МСК'],['Событие','Тест 50% FVG D1'],['Группа','13 исходных записей']])}<details open><summary>Исходные записи</summary>${[1,2,3].map(n=>`<p class="small muted">#demo-${n} · 23:59:${String(n).padStart(2,'0')} · контекст сценария</p>`).join('')}<p class="sub">Фрагмент демонстрационной группы.</p></details><div class="row"><button data-action="close">Закрыть</button><button class="primary" data-action="event-chart">К событию на графике</button></div>`;
 if(type==='zone')body=`${facts([['Границы','83 528,98–84 379,31'],['Тип / таймфрейм','OB / D1'],['Рыночное состояние','Актуальна'],['Геометрия','Не проверена']])}<div class="row"><button data-action="close">Закрыть</button><button data-modal="bounds">Исправить границы</button><button class="primary" data-page="review">Проверить</button></div>`;
 if(type==='processing')body=`${facts([['Данные на','09.10.2026 · 03:00 МСК'],['Состояние','Демонстрация'],['Активные сетапы','125'],['Проверка','108']])}<p class="sub">В production здесь отображаются обработанные активы, очередь, ошибки и время завершения из API.</p><div class="row"><button data-action="close">Закрыть</button><button data-action="recalc">Пересчитать</button></div>`;
 d.innerHTML=`<h2 id="dialog-title">${title}</h2>${body}`;if(!d.open)d.showModal();}
document.addEventListener('click',e=>{const b=e.target.closest('button,a,tr[data-page],tr[data-setup]');if(!b)return;const ds=b.dataset;if(ds.page){if($('#dialog').open)$('#dialog').close();state.page=ds.page;state.bucket='all';location.hash=ds.page;render();return}if(ds.setup){state.asset=ds.setup;state.page='setup';render();return}for(const [attr,key] of [['mode','mode'],['inspector','inspector'],['market','market'],['setting','setting'],['filter','filter'],['bucket','bucket'],['log','log']])if(ds[attr]!==undefined){state[key]=ds[attr];render();return}if(ds.overviewFilter){if(ds.overviewFilter==='review'){state.page='review';state.reviewDone=true;state.reviewResult='Очередь пуста по данным исходного обзора.'}else state.filter=ds.overviewFilter;render();return}if(ds.modal){openModal(ds.modal);return}if(ds.decision){state.reviewResult=ds.decision;state.reviewDone=true;render();toast('Пример решения сохранён в макете');return}if(ds.formSave){const lo=Number($('#lower').value),hi=Number($('#upper').value);if(!Number.isFinite(lo)||!Number.isFinite(hi)||lo<=0||hi<lo){$('#form-error').textContent='Укажите положительные границы: нижняя не должна превышать верхнюю.';return}$('#dialog').close();toast('Демонстрационный диапазон сохранён');return}if(ds.chartView){toast('Пример: режим графика «'+b.textContent+'». Полное поведение описано в ТЗ.');return}
 const a=ds.action;if(a==='close')$('#dialog').close();if(a==='watch'){state.watch=!state.watch;render()}if(a==='enabled'){state.enabled=!state.enabled;render();toast('Изменено только состояние макета')}if(a==='layers'){state.layers=!state.layers;render()}if(a==='reset-review'){state.reviewDone=false;render()}if(a==='filters'){state.filters=!state.filters;render()}if(a==='apply-filters')toast('Расширенные фильтры показаны как пример; подключение к API — по ТЗ');if(a==='reset-filters'){state.search='';state.filters=false;render()}if(a==='focus')toast('Пример фокусировки графика. В реализации — переход к нужной свече или диапазону.');if(a==='event-chart'){$('#dialog').close();state.page='desk';render();toast('Рабочее место открыто; привязка к реальной свече — в реализации')}if(a==='zone-table')openModal('zone');if(a==='asset-toggle'){b.textContent=b.textContent==='Включить'?'Выключить':'Включить';b.setAttribute('aria-pressed',String(b.textContent==='Выключить'));toast('Демонстрационный переключатель анализа')}if(a==='save-settings'){state.dirty=false;render();toast('Демонстрационные изменения сохранены')}if(a==='cancel-settings'){state.dirty=false;render();toast('Демонстрационные изменения отменены')}if(a==='range-preview')toast('Проверка формы доступна при сохранении; пересчёт сервером — по ТЗ');if(a==='recalc')toast('Пример: пересчёт в макете не запускается');if(a==='export'){const blob=new Blob([JSON.stringify({demo:true,decision:state.reviewResult||null},null,2)],{type:'application/json'});const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download='demo-reviews.json';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000)}if(['png','png2'].includes(a))toast('Экспорт реального графика PNG / PNG 2× сохраняется в реализации');});
document.addEventListener('input',e=>{if(e.target.id==='search'){state.search=e.target.value;$('#screen-table').innerHTML=screenerTable(assets.filter(a=>a[0].toLowerCase().includes(state.search.toLowerCase())))}if(e.target.hasAttribute('data-setting-field')){state.dirty=true;$('#dirty-label').textContent='Есть несохранённые изменения';$('[data-action="save-settings"]').disabled=false}});
document.addEventListener('change',e=>{if(e.target.id==='theme-select'){state.theme=e.target.value==='system'?(matchMedia('(prefers-color-scheme: light)').matches?'light':'dark'):e.target.value;document.documentElement.dataset.theme=state.theme;$('#theme').innerHTML=icon(state.theme==='dark'?'sun':'moon')}});
$('#theme').onclick=()=>{state.theme=state.theme==='dark'?'light':'dark';render()};
window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);if(pages[p]&&p!==state.page){state.page=p;render()}});
if(pages[location.hash.slice(1)])state.page=location.hash.slice(1);render();
